<div class="page-head"><div><h1><?=e($title)?></h1><p>Vincule a obrigação a um cliente e defina o vencimento.</p></div><a class="btn secondary" href="/obrigacoes">Voltar</a></div>
<?php if(!$clients):?><div class="alert error">Cadastre pelo menos um cliente antes de criar uma obrigação.</div><?php endif;?>
<form class="panel form-grid" method="post" action="<?=isset($item['id'])?'/obrigacoes/atualizar':'/obrigacoes/salvar'?>"><?=csrf_field()?><?php if(isset($item['id'])):?><input type="hidden" name="id" value="<?=$item['id']?>"><?php endif;?>
<div class="wide"><label>Cliente *</label><select name="cliente_id"><option value="">Selecione</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=((int)($item['cliente_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['nome'])?></option><?php endforeach;?></select><?php if(isset($errors['cliente_id'])):?><small class="field-error"><?=e($errors['cliente_id'])?></small><?php endif;?></div>
<div><label>Obrigação *</label><input name="titulo" value="<?=e($item['titulo']??'')?>" placeholder="Ex.: DAS - Simples Nacional"><?php if(isset($errors['titulo'])):?><small class="field-error"><?=e($errors['titulo'])?></small><?php endif;?></div>
<div><label>Vencimento *</label><input type="date" name="vencimento" value="<?=e($item['vencimento']??'')?>"><?php if(isset($errors['vencimento'])):?><small class="field-error"><?=e($errors['vencimento'])?></small><?php endif;?></div>
<div><label>Status</label><select name="status"><?php foreach(['Pendente','Em andamento','Concluída'] as $s):?><option <?=$s===($item['status']??'Pendente')?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div>
<div><label>Descrição</label><input name="descricao" value="<?=e($item['descricao']??'')?>"></div><div class="wide"><button class="btn" <?=$clients?'':'disabled'?>>Salvar obrigação</button></div></form>